def solve(rows):
  """Calculates the total cost of rows according to the given rules.

  Args:
    rows: A list of nonnegative integer quantities representing rows.

  Returns:
    The total cost in cents.
  """
  audit_positions = [(i, row) for i, row in enumerate(rows)]
  filtered_positions = [(i, row) for i, row in audit_positions if i % 5 != 0 and i != len(rows) - 1]

  if not filtered_positions:
    return 0

  rotated_rows = []
  row_lengths = [row for _, row in filtered_positions]
  for length in row_lengths:
    rotated_rows.insert(0, row_lengths[filtered_positions.index((filtered_positions[0][0], filtered_positions[0][1]))] % length)

  total_cost = 0
  for row in rotated_rows:
    if row == 0: 
      continue
    cost = 0
    if row <= 14:
      cost = row * 7
    else:
      cost = 14 * 7 + (row - 14) * 6
    if cost <= 111:
      total_cost += cost
    else:
      total_cost += 111

  return total_cost

